/* @autogenerated */
import { signal } from '@angular/core';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { BehaviorSubject, of } from 'rxjs';
import { ToolbarComponent } from './toolbar.component';
import { IdentityService } from '@shared/context/identity/identity.service';
import { AppStateService, ContextValue } from '@shared/context/state/app-state.service';
import { RuntimeConfigService } from '@shared/context/config/app-config.service';

describe('ToolbarComponent', () => {
  let fixture: ComponentFixture<ToolbarComponent>;
  let component: ToolbarComponent;
  let identityMock: any;
  let appStateMock: any;
  let tenantCtx$: BehaviorSubject<any>;
  let tenantSetSpy: jasmine.Spy;

  beforeEach(async () => {
    identityMock = {
      login: jasmine.createSpy('login'),
      logout: jasmine.createSpy('logout'),
    };

    const lang$ = new BehaviorSubject<string>('es');
    const tenant$ = new BehaviorSubject<string>('main');
    tenantCtx$ = new BehaviorSubject<any>(null);
    tenantSetSpy = jasmine.createSpy('tenantContextSet');
    (tenantCtx$ as any).set = tenantSetSpy;

    appStateMock = {
      language: lang$,
      tenant: tenant$,
      context: {
        tenant: tenantCtx$,
      },
    };

    await TestBed.configureTestingModule({
      imports: [ToolbarComponent],
      providers: [
        { provide: IdentityService, useValue: identityMock },
        { provide: AppStateService, useValue: appStateMock },
        {
          provide: RuntimeConfigService,
          useValue: { value: (path: string) => signal(path === 'meta.title' ? 'Phylax' : undefined) },
        },
      ],
    })
      .overrideComponent(ToolbarComponent, {
        set: { template: '' },
      })
      .compileComponents();

    fixture = TestBed.createComponent(ToolbarComponent);
    component = fixture.componentInstance;
  });

  it('builds providerList from providers input', () => {
    const providers = { tenant: { selector: () => of([]) } as any };
    fixture.componentRef.setInput('providers', providers);
    fixture.detectChanges();

    const list = component.providerList();
    expect(list.length).toBe(1);
    expect(list[0].key).toBe('tenant');
    expect(list[0].value).toBe(providers.tenant);
  });

  it('syncs providers to form controls on init', () => {
    fixture.componentRef.setInput('providers', { tenant: {} as any });
    fixture.detectChanges();
    component.ngOnInit();

    expect(component.form.contains('tenant')).toBeTrue();
  });

  it('propagates non-empty form values into app context as fixed ContextValue', () => {
    fixture.componentRef.setInput('providers', { tenant: {} as any });
    fixture.detectChanges();
    component.ngOnInit();

    component.form.controls['tenant'].setValue('acme');

    expect(tenantSetSpy).toHaveBeenCalled();
    const arg = tenantSetSpy.calls.mostRecent().args[0] as ContextValue;
    expect(arg.label).toBe('tenant');
    expect(arg.value).toBe('acme');
    expect(arg.fixed).toBeTrue();
    expect(arg.toFilter).toBeTrue();
  });

  it('updates control value when context emits values', () => {
    fixture.componentRef.setInput('providers', { tenant: {} as any });
    fixture.detectChanges();
    component.ngOnInit();

    tenantCtx$.next(ContextValue.fixed('tenant', 'globex'));

    expect(component.form.controls['tenant'].value).toBe('globex');
  });

  it('emits menuClicked event on toggle', () => {
    let called = false;
    component.menuClicked.subscribe(() => (called = true));

    component.toogleMenu();

    expect(called).toBeTrue();
  });

  it('delegates login and logout to IdentityService', () => {
    component.login();
    component.logout();

    expect(identityMock.login).toHaveBeenCalledWith('main');
    expect(identityMock.logout).toHaveBeenCalledWith('main');
  });

  it('unsubscribes subscriptions on destroy', () => {
    fixture.componentRef.setInput('providers', { tenant: {} as any });
    fixture.detectChanges();
    component.ngOnInit();

    expect(() => component.ngOnDestroy()).not.toThrow();
  });
});
